# filename: reconciliation_service/scheduler.py

import logging
from datetime import datetime, timezone

import config
import httpx
from apscheduler.schedulers.asyncio import AsyncIOScheduler
from apscheduler.triggers.cron import CronTrigger
from models import ReconcileRequest, ScheduleConfig, TriggerType

logger = logging.getLogger("scheduler")


class ReconciliationScheduler:
    JOB_ID = "eod_reconciliation"

    def __init__(self, reconciler):
        self.reconciler         = reconciler
        self.scheduler          = AsyncIOScheduler(timezone=config.EOD_TIMEZONE)
        self.cfg                = ScheduleConfig(
            hour=config.EOD_HOUR, minute=config.EOD_MINUTE,
            timezone=config.EOD_TIMEZONE, limit=config.RECON_LIMIT
        )
        self.last_run_at        : str | None = None
        self.last_run_id        : str | None = None
        self.last_run_status    : str | None = None
        self.total_scheduled_runs = 0

    # ── Lifecycle ─────────────────────────────────────────────────────────────

    def start(self):
        if self.cfg.enabled:
            self._add_job()
        self.scheduler.start()
        logger.info(
            f"Scheduler started — EOD job at {self.cfg.hour:02d}:{self.cfg.minute:02d} "
            f"{self.cfg.timezone} [enabled={self.cfg.enabled}]"
        )

    def shutdown(self):
        self.scheduler.shutdown(wait=False)
        logger.info("Scheduler stopped")

    # ── Public control ────────────────────────────────────────────────────────

    def update(self, new_cfg: ScheduleConfig):
        self.cfg = new_cfg
        if self.scheduler.get_job(self.JOB_ID):
            self.scheduler.remove_job(self.JOB_ID)
        if new_cfg.enabled:
            self._add_job()
        logger.info(
            f"Schedule updated — {new_cfg.hour:02d}:{new_cfg.minute:02d} "
            f"{new_cfg.timezone} enabled={new_cfg.enabled}"
        )

    def status(self) -> dict:
        job      = self.scheduler.get_job(self.JOB_ID)
        next_run = str(job.next_run_time) if job else None
        return {
            "enabled"              : self.cfg.enabled,
            "next_run"             : next_run,
            "last_run"             : self.last_run_at,
            "last_run_id"          : self.last_run_id,
            "last_run_status"      : self.last_run_status,
            "hour"                 : self.cfg.hour,
            "minute"               : self.cfg.minute,
            "timezone"             : self.cfg.timezone,
            "total_scheduled_runs" : self.total_scheduled_runs,
        }

    def pause(self):
        if self.scheduler.get_job(self.JOB_ID):
            self.scheduler.pause_job(self.JOB_ID)
            self.cfg.enabled = False
            logger.info("EOD job paused")

    def resume(self):
        if self.scheduler.get_job(self.JOB_ID):
            self.scheduler.resume_job(self.JOB_ID)
            self.cfg.enabled = True
            logger.info("EOD job resumed")
        else:
            self._add_job()
            self.cfg.enabled = True

    # ── Job ───────────────────────────────────────────────────────────────────

    def _add_job(self):
        self.scheduler.add_job(
            self._run_eod,
            CronTrigger(hour=self.cfg.hour, minute=self.cfg.minute, timezone=self.cfg.timezone),
            id=self.JOB_ID, replace_existing=True,
            name="End-of-Day Reconciliation"
        )

    async def _run_eod(self):
        import uuid
        run_id = f"recon_eod_{datetime.now(tz=timezone.utc).strftime('%Y%m%d_%H%M%S')}_{uuid.uuid4().hex[:6]}"
        logger.info(f"EOD reconciliation started — run_id={run_id}")
        self.total_scheduled_runs += 1
        self.last_run_at = str(datetime.now(tz=timezone.utc))

        req = ReconcileRequest(limit=self.cfg.limit)
        await self.reconciler.run(run_id, req, trigger=TriggerType.SCHEDULED)

        result = self.reconciler.get_result(run_id)
        self.last_run_id     = run_id
        self.last_run_status = result.get("status", "unknown") if isinstance(result, dict) else result.status

        logger.info(
            f"EOD run complete — run_id={run_id} "
            f"payments={getattr(result, 'total_payments', '?')} "
            f"discrepancies={getattr(result, 'discrepancies_found', '?')}"
        )
        await self._notify_eod(result, run_id)

    async def _notify_eod(self, result, run_id: str):
        """Push EOD summary to notification service."""
        try:
            discrepancies = getattr(result, "discrepancies_found", 0)
            total         = getattr(result, "total_payments", 0)
            reconciled    = getattr(result, "reconciled", 0)
            payload = {
                "event"          : "reconciliation.eod_completed",
                "payment_id"     : run_id,
                "merchant_id"    : "platform",
                "amount"         : discrepancies,
                "currency"       : "N/A",
                "customer_name"  : "System",
                "merchant_email" : "ops@platform.com",
                "customer_email" : "ops@platform.com",
                "metadata"       : {
                    "run_id"       : run_id,
                    "total"        : total,
                    "reconciled"   : reconciled,
                    "discrepancies": discrepancies,
                    "status"       : self.last_run_status,
                }
            }
            async with httpx.AsyncClient(timeout=5) as client:
                await client.post(f"{config.NOTIFY}/notify", json=payload)
            logger.info(f"EOD notification sent for run {run_id}")
        except Exception as e: # noqa: BLE001
            logger.warning(f"EOD notification failed: {e}")
